mapper.select:
SELECT * FROM handling_activity
WHERE tracking_number = #{trackingNumber}
ORDER BY occurred_at ASC, activity_id ASC

SELECT * FROM handling_activity
ORDER BY occurred_at DESC, activity_id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM handling_activity
WHERE tracking_number = #{trackingNumber}
  AND handling_type   = #{handlingType}
  AND unlocode        = #{unlocode}
  AND occurred_at >= #{windowStart}
  AND occurred_at <  #{windowEnd}
